public class CouponTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Coupon a = new Coupon("SAVE10", 10);
        Coupon b = new Coupon("SAVE10", 10);
        Coupon c = new Coupon("SAVE10", 25);
        Coupon d = new Coupon("BOGO", 10);

        check("reflexive: a.equals(a)", true, a.equals(a));
        check("equal fields: a.equals(b)", true, a.equals(b));
        check("symmetric: b.equals(a)", true, b.equals(a));
        check("different percent: a.equals(c)", false, a.equals(c));
        check("different code: a.equals(d)", false, a.equals(d));
        check("a.equals(null)", false, a.equals(null));
        check("different class: a.equals(\"SAVE10\")", false, a.equals("SAVE10"));

        Coupon sub = new Coupon("SAVE10", 10) { };
        check("subclass instance is not equal (getClass check)", false, a.equals(sub));

        check("null codes compare equal", true, new Coupon(null, 5).equals(new Coupon(null, 5)));
        check("equal coupons share a hash code", true, a.hashCode() == b.hashCode());
        check("toString()", "SAVE10 (10%)", a.toString());

        java.util.HashSet<Coupon> set = new java.util.HashSet<>();
        set.add(a);
        set.add(b);
        check("HashSet treats equal coupons as one", 1, set.size());
        set.add(c);
        check("HashSet size after adding a different coupon", 2, set.size());
        check("HashSet contains a freshly built equal coupon", true, set.contains(new Coupon("SAVE10", 10)));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

